        match producer.enqueue(&payload) {
            STATUS_OK => {
                counts.enqueued = counts.enqueued.wrapping_add(1);
                add_fingerprint(&mut counts.enqueued_fingerprint, keys, value);
            }
            STATUS_FULL => counts.full = counts.full.wrapping_add(1),
