	if config.operations <= 0 {
		return errors.New("operations must be greater than zero")
	}
	if config.operations > maxOperationsPerHistory {
		return fmt.Errorf(
			"operations must not exceed %d per history; increase trials for more coverage",
			maxOperationsPerHistory,
		)
	}
	if config.trials <= 0 {
		return errors.New("trials must be greater than zero")
	}
	// Porcupine reads a zero timeout as unlimited, which is the hang this
	// budget exists to prevent, so the gate requires a positive one.
	if config.checkBudget <= 0 {
		return errors.New("check budget must be greater than zero")
	}
	if _, _, err := workerCounts(config.scenario, config.producers, config.consumers); err != nil {
		return err
	}
	if err := runABIProfiles(config); err != nil {
		return err
	}

	capacities := accuracyCapacities(config.capacity)
	for _, capacity := range capacities {
		capacityConfig := config
		capacityConfig.capacity = capacity
		boundary, err := runBoundaryHistory(capacityConfig)
		if err != nil {
			return fmt.Errorf("boundary history at capacity %d: %w", capacity, err)
		}
		verdict := checkScenarioHistory(
			config.scenario,
			int(capacity),
			boundary,
			config.checkBudget,
		)
		if err := gateFailure(
			verdict,
			config,
			fmt.Sprintf("boundary history at capacity %d", capacity),
		); err != nil {
			return errors.Join(err, writeFailureHistory(config.failureHistory, boundary))
		}
	}

	for trial := 0; trial < config.trials; trial++ {
		capacity := capacities[trial%len(capacities)]
		trialConfig := config
		trialConfig.capacity = capacity
		history, err := runConcurrentHistory(trialConfig, trial)
		if err != nil {
			return fmt.Errorf(
				"trial %d (seed %d, capacity %d): %w",
				trial,
				config.seed+int64(trial),
				capacity,
				err,
			)
		}
		verdict := checkScenarioHistory(
			config.scenario,
			int(capacity),
			history,
			config.checkBudget,
		)
		if err := gateFailure(
			verdict,
			config,
			fmt.Sprintf(
				"trial %d (seed %d, capacity %d)",
				trial,
				config.seed+int64(trial),
				capacity,
			),
		); err != nil {
			return errors.Join(err, writeFailureHistory(config.failureHistory, history))
		}
	}
	return nil
}

