#![deny(unsafe_op_in_unsafe_fn)]

mod ffi;

use std::alloc::{alloc_zeroed, dealloc, Layout};
use std::cell::Cell;
use std::ptr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

const ABI_VERSION: u32 = 1;
const STATUS_OK: u32 = 0;
const STATUS_FULL: u32 = 1;
const STATUS_EMPTY: u32 = 2;
const STATUS_INVALID: u32 = 3;
const STATUS_INTERNAL_ERROR: u32 = 4;

/// `hw.cachelinesize` on the Apple M4 host. The two shared indices and the two
/// handles each occupy a whole line so one side's store never invalidates the
/// line the other side reads.
const CACHE_LINE: usize = 128;

/// Every slot stores its own length ahead of its payload, so one enqueue or
/// dequeue at the benchmark's 8-byte value size touches exactly one line.
const HEADER_SIZE: usize = 8;

/// Slot stride alignment. Keeps the length header and an 8-byte payload inside
/// one naturally aligned 16-byte pair.
const SLOT_ALIGN: usize = 16;

#[repr(C, align(128))]
struct PaddedIndex(AtomicU64);

/// Shared queue core: one preallocated slot slab plus two monotonic indices.
///
/// `tail` and `head` count operations rather than slot positions, which makes
/// full (`tail - head == capacity`) and empty (`tail == head`) exact without
/// sacrificing a slot. The slab holds `slot_mask + 1` slots, a power of two, so
/// the slot for an index is a mask instead of a division; the logical bound is
/// enforced by `capacity`, which may be smaller than the slot count.
struct QueueState {
    tail: PaddedIndex,
    head: PaddedIndex,
    slab: *mut u8,
    layout: Layout,
    slot_mask: u64,
    stride: usize,
    capacity: u64,
    max_value_size: usize,
}

// The slab is shared, but the index ordering below guarantees the producer and
// the consumer never touch the same slot concurrently.
unsafe impl Send for QueueState {}
unsafe impl Sync for QueueState {}

impl Drop for QueueState {
    fn drop(&mut self) {
        unsafe { dealloc(self.slab, self.layout) };
    }
}

pub struct Queue {
    producer_count: u32,
    consumer_count: u32,
    state: Arc<QueueState>,
}

impl Queue {
    fn new(
        capacity: u64,
        max_value_size: u64,
        producer_count: u32,
        consumer_count: u32,
    ) -> Result<Self, u32> {
        if capacity == 0 || max_value_size == 0 || producer_count == 0 || consumer_count == 0 {
            return Err(STATUS_INVALID);
        }

        let max_value_size = usize::try_from(max_value_size).map_err(|_| STATUS_INVALID)?;
        let slots = capacity
            .checked_next_power_of_two()
            .ok_or(STATUS_INTERNAL_ERROR)?;
        let slot_count = usize::try_from(slots).map_err(|_| STATUS_INTERNAL_ERROR)?;
        let stride = HEADER_SIZE
            .checked_add(max_value_size)
            .and_then(|size| size.checked_add(SLOT_ALIGN - 1))
            .map(|size| size & !(SLOT_ALIGN - 1))
            .ok_or(STATUS_INTERNAL_ERROR)?;
        let bytes = stride
            .checked_mul(slot_count)
            .ok_or(STATUS_INTERNAL_ERROR)?;
        let layout =
            Layout::from_size_align(bytes, SLOT_ALIGN).map_err(|_| STATUS_INTERNAL_ERROR)?;
        // Fallible by contract: the crate aborts on panic, so a failed slab must
        // surface as an ABI status rather than an allocation error handler.
        let slab = unsafe { alloc_zeroed(layout) };
        if slab.is_null() {
            return Err(STATUS_INTERNAL_ERROR);
        }

        Ok(Self {
            producer_count,
            consumer_count,
            state: Arc::new(QueueState {
                tail: PaddedIndex(AtomicU64::new(0)),
                head: PaddedIndex(AtomicU64::new(0)),
                slab,
                layout,
                slot_mask: slots - 1,
                stride,
                capacity,
                max_value_size,
            }),
        })
    }

    fn producer(&self, id: u32) -> Result<Producer, u32> {
        if id >= self.producer_count {
            return Err(STATUS_INVALID);
        }
        let state = &self.state;
        Ok(Producer {
            tail: &state.tail.0,
            head: &state.head.0,
            slab: state.slab,
            cached_head: Cell::new(state.head.0.load(Ordering::Acquire)),
            slot_mask: state.slot_mask,
            stride: state.stride,
            capacity: state.capacity,
            max_value_size: state.max_value_size,
            state: Arc::clone(state),
        })
    }

    fn consumer(&self, id: u32) -> Result<Consumer, u32> {
        if id >= self.consumer_count {
            return Err(STATUS_INVALID);
        }
        let state = &self.state;
        Ok(Consumer {
            head: &state.head.0,
            tail: &state.tail.0,
            slab: state.slab,
            cached_tail: Cell::new(state.tail.0.load(Ordering::Acquire)),
            slot_mask: state.slot_mask,
            stride: state.stride,
            state: Arc::clone(state),
        })
    }
}

/// Producer handle. The hot fields are copied out of `QueueState` so the fast
/// path never chases the `Arc`, and `cached_head` lets a non-full queue avoid
/// loading the consumer's line at all. `state` keeps the core alive.
#[repr(C, align(128))]
pub struct Producer {
    tail: *const AtomicU64,
    head: *const AtomicU64,
    slab: *mut u8,
    cached_head: Cell<u64>,
    slot_mask: u64,
    stride: usize,
    capacity: u64,
    max_value_size: usize,
    state: Arc<QueueState>,
}

// One handle is used by one thread; `align(128)` keeps two handles off one line.
unsafe impl Send for Producer {}

impl Producer {
    #[inline(always)]
    fn try_enqueue(&self, data: &[u8]) -> u32 {
        let length = data.len();
        if length > self.max_value_size {
            return STATUS_INVALID;
        }

        let tail = unsafe { (*self.tail).load(Ordering::Relaxed) };
        let mut head = self.cached_head.get();
        if tail.wrapping_sub(head) >= self.capacity {
            // FULL is only returned after a fresh view of the peer index, so it
            // can never be reported while the abstract queue has room.
            head = unsafe { (*self.head).load(Ordering::Acquire) };
            self.cached_head.set(head);
            if tail.wrapping_sub(head) >= self.capacity {
                return STATUS_FULL;
            }
        }

        unsafe {
            let slot = self
                .slab
                .add(((tail & self.slot_mask) as usize).wrapping_mul(self.stride));
            ptr::write_unaligned(slot as *mut u64, length as u64);
            let payload = slot.add(HEADER_SIZE);
            if length == 8 {
                // The measured workload is fixed at 8 bytes; a single word move
                // keeps `memcpy` off the hot path.
                ptr::write_unaligned(
                    payload as *mut u64,
                    ptr::read_unaligned(data.as_ptr() as *const u64),
                );
            } else if length != 0 {
                ptr::copy_nonoverlapping(data.as_ptr(), payload, length);
            }
            // Publishes the header and payload written above.
            (*self.tail).store(tail.wrapping_add(1), Ordering::Release);
        }
        STATUS_OK
    }
}

/// Consumer handle, the mirror image of [`Producer`].
#[repr(C, align(128))]
pub struct Consumer {
    head: *const AtomicU64,
    tail: *const AtomicU64,
    slab: *mut u8,
    cached_tail: Cell<u64>,
    slot_mask: u64,
    stride: usize,
    state: Arc<QueueState>,
}

unsafe impl Send for Consumer {}

impl Consumer {
    #[inline(always)]
    fn try_dequeue(&self, output: &mut [u8]) -> Result<usize, u32> {
        let head = unsafe { (*self.head).load(Ordering::Relaxed) };
        let mut tail = self.cached_tail.get();
        if head == tail {
            // EMPTY is only returned after a fresh view of the peer index.
            tail = unsafe { (*self.tail).load(Ordering::Acquire) };
            self.cached_tail.set(tail);
            if head == tail {
                return Err(STATUS_EMPTY);
            }
        }

        unsafe {
            let slot = self
                .slab
                .add(((head & self.slot_mask) as usize).wrapping_mul(self.stride));
            let length = ptr::read_unaligned(slot as *const u64) as usize;
            // Checked before any byte moves, so an undersized output leaves the
            // caller's buffer and the value itself untouched.
            if length > output.len() {
                return Err(STATUS_INVALID);
            }
            let payload = slot.add(HEADER_SIZE);
            if length == 8 {
                ptr::write_unaligned(
                    output.as_mut_ptr() as *mut u64,
                    ptr::read_unaligned(payload as *const u64),
                );
            } else if length != 0 {
                ptr::copy_nonoverlapping(payload, output.as_mut_ptr(), length);
            }
            // Releases the slot back to the producer.
            (*self.head).store(head.wrapping_add(1), Ordering::Release);
            Ok(length)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::AtomicBool;
    use std::thread;

    const MIB: u64 = 1 << 20;

    fn payload(length: usize, tag: u8) -> Vec<u8> {
        (0..length)
            .map(|index| {
                tag.wrapping_mul(31)
                    .wrapping_add((index as u8).wrapping_mul(17))
                    .wrapping_add(0x4d)
            })
            .collect()
    }

    #[test]
    fn safe_core_is_bounded_fifo() {
        let queue = Queue::new(2, 8, 1, 1).unwrap();
        let producer = queue.producer(0).unwrap();
        let consumer = queue.consumer(0).unwrap();

        assert_eq!(producer.try_enqueue(b"first"), STATUS_OK);
        assert_eq!(producer.try_enqueue(b"second"), STATUS_OK);
        assert_eq!(producer.try_enqueue(b"third"), STATUS_FULL);

        let mut output = [0_u8; 8];
        assert_eq!(consumer.try_dequeue(&mut output), Ok(5));
        assert_eq!(&output[..5], b"first");
        assert_eq!(consumer.try_dequeue(&mut output), Ok(6));
        assert_eq!(&output[..6], b"second");
        assert_eq!(consumer.try_dequeue(&mut output), Err(STATUS_EMPTY));
    }

    #[test]
    fn failed_dequeue_leaves_value_and_output_unchanged() {
        let queue = Queue::new(1, 8, 1, 1).unwrap();
        let producer = queue.producer(0).unwrap();
        let consumer = queue.consumer(0).unwrap();
        assert_eq!(producer.try_enqueue(b"value"), STATUS_OK);

        let mut short = [0xA5_u8; 4];
        assert_eq!(consumer.try_dequeue(&mut short), Err(STATUS_INVALID));
        assert_eq!(short, [0xA5; 4]);

        let mut output = [0_u8; 8];
        assert_eq!(consumer.try_dequeue(&mut output), Ok(5));
        assert_eq!(&output[..5], b"value");
    }

    #[test]
    fn rejects_invalid_configuration_and_handle_ids() {
        assert_eq!(Queue::new(0, 8, 1, 1).err(), Some(STATUS_INVALID));
        assert_eq!(Queue::new(1, 0, 1, 1).err(), Some(STATUS_INVALID));
        assert_eq!(Queue::new(1, 8, 0, 1).err(), Some(STATUS_INVALID));
        assert_eq!(Queue::new(1, 8, 1, 0).err(), Some(STATUS_INVALID));

        let queue = Queue::new(4, 8, 1, 1).unwrap();
        assert!(queue.producer(1).is_err());
        assert!(queue.consumer(1).is_err());
        assert!(queue.producer(0).is_ok());
        assert!(queue.consumer(0).is_ok());
    }

    #[test]
    fn oversized_value_is_rejected_without_queueing() {
        let queue = Queue::new(2, 8, 1, 1).unwrap();
        let producer = queue.producer(0).unwrap();
        let consumer = queue.consumer(0).unwrap();

        assert_eq!(producer.try_enqueue(&payload(9, 0x11)), STATUS_INVALID);
        let mut output = [0_u8; 8];
        assert_eq!(consumer.try_dequeue(&mut output), Err(STATUS_EMPTY));
    }

    /// The mask wrap and the exact FULL/EMPTY boundary at every gate capacity,
    /// driven past the end of the slab several times.
    #[test]
    fn boundary_and_wrap_hold_at_small_capacities() {
        for capacity in [1_u64, 2, 3, 7, 8] {
            let queue = Queue::new(capacity, 8, 1, 1).unwrap();
            let producer = queue.producer(0).unwrap();
            let consumer = queue.consumer(0).unwrap();
            let mut output = [0_u8; 8];
            let mut sequence = 0_u64;

            for round in 0..4_u64 {
                for index in 0..capacity {
                    let value = sequence.wrapping_add(index);
                    assert_eq!(
                        producer.try_enqueue(&value.to_le_bytes()),
                        STATUS_OK,
                        "capacity {capacity} round {round} item {index}"
                    );
                }
                assert_eq!(
                    producer.try_enqueue(&sequence.to_le_bytes()),
                    STATUS_FULL,
                    "capacity {capacity} round {round} overfill"
                );

                for index in 0..capacity {
                    assert_eq!(consumer.try_dequeue(&mut output), Ok(8));
                    assert_eq!(
                        u64::from_le_bytes(output),
                        sequence.wrapping_add(index),
                        "capacity {capacity} round {round} item {index}"
                    );
                }
                assert_eq!(
                    consumer.try_dequeue(&mut output),
                    Err(STATUS_EMPTY),
                    "capacity {capacity} round {round} overdrain"
                );
                sequence = sequence.wrapping_add(capacity);
            }
        }
    }

    /// A single free slot must be reusable immediately, which is the case that
    /// distinguishes a correct monotonic bound from an off-by-one.
    #[test]
    fn single_slot_release_is_immediate() {
        let queue = Queue::new(3, 8, 1, 1).unwrap();
        let producer = queue.producer(0).unwrap();
        let consumer = queue.consumer(0).unwrap();
        let mut output = [0_u8; 8];

        for value in 0..3_u64 {
            assert_eq!(producer.try_enqueue(&value.to_le_bytes()), STATUS_OK);
        }
        for value in 3..40_u64 {
            assert_eq!(producer.try_enqueue(&value.to_le_bytes()), STATUS_FULL);
            assert_eq!(consumer.try_dequeue(&mut output), Ok(8));
            assert_eq!(u64::from_le_bytes(output), value - 3);
            assert_eq!(producer.try_enqueue(&value.to_le_bytes()), STATUS_OK);
        }
    }

    /// The lengths the correctness gate probes, at the gate's two larger ABI
    /// profiles, including zero-length and maximum-length values.
    #[test]
    fn mixed_lengths_round_trip_in_fifo_order() {
        for (capacity, max_value_size) in [(3_u64, 257_u64), (7, 257), (3, MIB)] {
            let max = max_value_size as usize;
            let mut lengths = vec![0, 1, 7, 8, 9, max / 2, max];
            lengths.retain(|length| *length <= max);
            lengths.sort_unstable();
            lengths.dedup();

            let queue = Queue::new(capacity, max_value_size, 1, 1).unwrap();
            let producer = queue.producer(0).unwrap();
            let consumer = queue.consumer(0).unwrap();
            let mut output = vec![0_u8; max];

            for chunk in lengths.chunks(capacity as usize) {
                let expected: Vec<Vec<u8>> = chunk
                    .iter()
                    .enumerate()
                    .map(|(tag, length)| payload(*length, tag as u8))
                    .collect();
                for value in &expected {
                    assert_eq!(
                        producer.try_enqueue(value),
                        STATUS_OK,
                        "capacity {capacity} max {max_value_size} length {}",
                        value.len()
                    );
                }
                for value in &expected {
                    assert_eq!(consumer.try_dequeue(&mut output), Ok(value.len()));
                    assert_eq!(&output[..value.len()], value.as_slice());
                }
                assert_eq!(consumer.try_dequeue(&mut output), Err(STATUS_EMPTY));
            }
        }
    }

    /// An undersized output must not consume the value, touch the buffer, or
    /// disturb the following item.
    #[test]
    fn undersized_output_retry_preserves_order() {
        for length in [1_usize, 8, 9, 257] {
            let queue = Queue::new(2, 257, 1, 1).unwrap();
            let producer = queue.producer(0).unwrap();
            let consumer = queue.consumer(0).unwrap();
            let first = payload(length, 0xf1);
            let second = payload(length, 0xf2);
            assert_eq!(producer.try_enqueue(&first), STATUS_OK);
            assert_eq!(producer.try_enqueue(&second), STATUS_OK);

            let mut short = vec![0xa7_u8; length - 1];
            let unchanged = short.clone();
            assert_eq!(consumer.try_dequeue(&mut short), Err(STATUS_INVALID));
            assert_eq!(short, unchanged, "length {length} clobbered short output");

            let mut output = vec![0_u8; 257];
            assert_eq!(consumer.try_dequeue(&mut output), Ok(length));
            assert_eq!(&output[..length], first.as_slice());
            assert_eq!(consumer.try_dequeue(&mut output), Ok(length));
            assert_eq!(&output[..length], second.as_slice());
        }
    }

    #[test]
    fn zero_length_values_round_trip() {
        let queue = Queue::new(3, 8, 1, 1).unwrap();
        let producer = queue.producer(0).unwrap();
        let consumer = queue.consumer(0).unwrap();

        for _ in 0..7 {
            assert_eq!(producer.try_enqueue(&[]), STATUS_OK);
            let mut empty: [u8; 0] = [];
            assert_eq!(consumer.try_dequeue(&mut empty), Ok(0));
        }

        assert_eq!(producer.try_enqueue(&[]), STATUS_OK);
        let mut output = [0xa7_u8; 8];
        assert_eq!(consumer.try_dequeue(&mut output), Ok(0));
        assert_eq!(output, [0xa7; 8], "zero-length dequeue wrote into output");
    }

    /// Two live threads across many wraps. This is the cheapest check that
    /// would catch a missing `Acquire` or `Release`: a lost publication shows
    /// up as a gap or a repeat in the sequence, and a lost release shows up as
    /// a conservation mismatch in the final drain.
    #[test]
    fn spsc_stress_conserves_sequence() {
        const ITEMS: u64 = 2_000_000;

        for capacity in [1_u64, 3, 1024] {
            let queue = Queue::new(capacity, 8, 1, 1).unwrap();
            let producer = queue.producer(0).unwrap();
            let consumer = queue.consumer(0).unwrap();
            let done = Arc::new(AtomicBool::new(false));
            let producer_done = Arc::clone(&done);

            let (enqueued, dequeued) = thread::scope(|scope| {
                let producer_worker = scope.spawn(move || {
                    let mut enqueued = 0_u64;
                    while enqueued < ITEMS {
                        match producer.try_enqueue(&enqueued.to_le_bytes()) {
                            STATUS_OK => enqueued += 1,
                            STATUS_FULL => {}
                            status => panic!("enqueue returned {status}"),
                        }
                    }
                    producer_done.store(true, Ordering::Release);
                    enqueued
                });
                let consumer_worker = scope.spawn(move || {
                    let mut output = [0_u8; 8];
                    let mut dequeued = 0_u64;
                    while dequeued < ITEMS {
                        match consumer.try_dequeue(&mut output) {
                            Ok(length) => {
                                assert_eq!(length, 8);
                                assert_eq!(
                                    u64::from_le_bytes(output),
                                    dequeued,
                                    "capacity {capacity} saw an out-of-order value"
                                );
                                dequeued += 1;
                            }
                            Err(STATUS_EMPTY) => {
                                if done.load(Ordering::Acquire) && dequeued == ITEMS {
                                    break;
                                }
                            }
                            Err(status) => panic!("dequeue returned {status}"),
                        }
                    }
                    dequeued
                });
                (
                    producer_worker.join().expect("producer thread"),
                    consumer_worker.join().expect("consumer thread"),
                )
            });

            assert_eq!(enqueued, ITEMS);
            assert_eq!(dequeued, ITEMS);
        }
    }

    /// Both indices are alone on their own cache line and handles cannot share
    /// one, which is the property the hot path's cache behavior depends on.
    #[test]
    fn shared_indices_and_handles_are_line_isolated() {
        assert_eq!(std::mem::size_of::<PaddedIndex>(), CACHE_LINE);
        assert_eq!(std::mem::align_of::<PaddedIndex>(), CACHE_LINE);
        assert_eq!(std::mem::size_of::<Producer>(), CACHE_LINE);
        assert_eq!(std::mem::align_of::<Producer>(), CACHE_LINE);
        assert_eq!(std::mem::size_of::<Consumer>(), CACHE_LINE);
        assert_eq!(std::mem::align_of::<Consumer>(), CACHE_LINE);

        let queue = Queue::new(1024, 8, 1, 1).unwrap();
        let state = &queue.state;
        let tail = &state.tail.0 as *const AtomicU64 as usize;
        let head = &state.head.0 as *const AtomicU64 as usize;
        assert_eq!(tail % CACHE_LINE, 0);
        assert_eq!(head % CACHE_LINE, 0);
        assert!(tail.abs_diff(head) >= CACHE_LINE);
        // The benchmark slab must stay well inside the 64 KiB L1D.
        assert_eq!(state.stride, 16);
        assert_eq!(state.layout.size(), 16 * 1024);
    }

    #[test]
    fn non_power_of_two_capacity_allocates_a_masked_slab() {
        for (capacity, slots) in [(1_u64, 1_u64), (2, 2), (3, 4), (7, 8), (1024, 1024)] {
            let queue = Queue::new(capacity, 8, 1, 1).unwrap();
            assert_eq!(queue.state.slot_mask, slots - 1, "capacity {capacity}");
            assert_eq!(queue.state.capacity, capacity);
        }
    }
}

