package main

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"sync"
	"time"
)

var (
	candidateOperationTimeout = 5 * time.Second
	abiProbeTimeout           = 15 * time.Second
)

type boundedLog struct {
	mu        sync.Mutex
	buffer    bytes.Buffer
	remaining int
}

func newBoundedLog(limit int) *boundedLog {
	return &boundedLog{remaining: limit}
}

func (w *boundedLog) Write(value []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	original := len(value)
	if len(value) > w.remaining {
		value = value[:w.remaining]
	}
	_, _ = w.buffer.Write(value)
	w.remaining -= len(value)
	return original, nil
}

func (w *boundedLog) String() string {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.buffer.String()
}

type candidateLane struct {
	conn net.Conn
	mu   sync.Mutex
}

type candidateSession struct {
	lanes     []candidateLane
	valueSize int
	done      chan struct{}
	log       *boundedLog
	waitMu    sync.Mutex
	waitErr   error
	closeOnce sync.Once
	closeErr  error
	process   *os.Process
	abortOnce sync.Once
}

type candidateConfig struct {
	workspace     string
	candidate     string
	useReference  bool
	scenario      scenario
	capacity      uint64
	valueSize     int
	laneCount     int
	producerCount int
	consumerCount int
	mixedLane     bool
}

func candidateLibraryPath(config candidateConfig) (string, error) {
	if config.useReference {
		return "", nil
	}
	path := config.candidate
	if !filepath.IsAbs(path) {
		path = filepath.Join(config.workspace, path)
	}
	stat, err := os.Stat(path)
	if err != nil {
		return "", fmt.Errorf("candidate library %q: %w", path, err)
	}
	if stat.IsDir() || !stat.Mode().IsRegular() {
		return "", fmt.Errorf("candidate library %q must be a regular file", path)
	}
	return path, nil
}

func candidateSourceArgs(config candidateConfig) ([]string, error) {
	if config.useReference {
		return []string{"--reference"}, nil
	}
	path, err := candidateLibraryPath(config)
	if err != nil {
		return nil, err
	}
	return []string{"--library", path}, nil
}

