args.content:
//! Local 1P/1C harness for `queue-candidate.so`.
//!
//! This is implementer tooling, not the canonical benchmark. It exists so a
//! candidate build can be compared against another build of the same ABI on
//! this host without paying for a trusted evaluation run. It deliberately
//! mirrors the trusted runner's measured loop -- same 8-byte sequence payload,
//! same per-success consumer fingerprint work, same clock-check interval, same
//! user-interactive QoS -- so the ratio it reports tracks the ratio the trusted
//! `total_ops_per_sec` would report.
//!
//! It lives outside `src/` and is compiled directly with `rustc`, so it has no
//! effect on the `cdylib` that `make` builds.
//!
//! Build and run:
//!
//! ```text
//! rustc -O bench/spsc_harness.rs -o /tmp/spsc_harness
//! /tmp/spsc_harness measure ./queue-candidate.so 1024 8 1.0 3.0
//! /tmp/spsc_harness verify  ./queue-candidate.so 1024 8 2000000
//! ```

use std::env;
use std::ffi::{c_char, c_int, c_void, CString};
use std::process;
use std::ptr;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Barrier};
use std::thread;
use std::time::{Duration, Instant};

const STATUS_OK: u32 = 0;
const STATUS_FULL: u32 = 1;
const STATUS_EMPTY: u32 = 2;

const RTLD_NOW: c_int = 2;
const QOS_CLASS_USER_INTERACTIVE: u32 = 0x21;
const CLOCK_CHECK_INTERVAL: u64 = 64;

extern "C" {
    fn dlopen(path: *const c_char, mode: c_int) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
    fn dlerror() -> *const c_char;
    fn pthread_set_qos_class_self_np(qos_class: u32, relative_priority: i32) -> c_int;
}

type AbiVersionFn = unsafe extern "C" fn() -> u32;
type QueueCreateFn = unsafe extern "C" fn(u64, u64, u32, u32, *mut *mut c_void) -> u32;
type QueueDestroyFn = unsafe extern "C" fn(*mut c_void);
type HandleCreateFn = unsafe extern "C" fn(*mut c_void, u32, *mut *mut c_void) -> u32;
type HandleDestroyFn = unsafe extern "C" fn(*mut c_void);
type EnqueueFn = unsafe extern "C" fn(*mut c_void, *const u8, u64) -> u32;
type DequeueFn = unsafe extern "C" fn(*mut c_void, *mut u8, u64, *mut u64) -> u32;

struct Abi {
    queue_create: QueueCreateFn,
    queue_destroy: QueueDestroyFn,
    producer_create: HandleCreateFn,
    producer_destroy: HandleDestroyFn,
    consumer_create: HandleCreateFn,
    consumer_destroy: HandleDestroyFn,
    enqueue: EnqueueFn,
    dequeue: DequeueFn,
}

/// The ABI is loaded once and the handles are per-thread by contract.
unsafe impl Send for Abi {}
unsafe impl Sync for Abi {}

#[derive(Clone, Copy)]
struct Handle(*mut c_void);
unsafe impl Send for Handle {}

fn load(path: &str) -> Abi {
    let c_path = CString::new(path).expect("library path");
    let handle = unsafe { dlopen(c_path.as_ptr(), RTLD_NOW) };
    if handle.is_null() {
        let error = unsafe { dlerror() };
        let message = if error.is_null() {
            "unknown dlopen failure".to_string()
        } else {
            unsafe { std::ffi::CStr::from_ptr(error) }
                .to_string_lossy()
                .into_owned()
        };
        die(&format!("dlopen {path}: {message}"));
    }

    let symbol = |name: &str| -> *mut c_void {
        let c_name = CString::new(name).expect("symbol name");
        let address = unsafe { dlsym(handle, c_name.as_ptr()) };
        if address.is_null() {
            die(&format!("{path} is missing {name}"));
        }
        address
    };

    let abi_version: AbiVersionFn = unsafe { std::mem::transmute(symbol("vsq_abi_version")) };
    let version = unsafe { abi_version() };
    if version != 1 {
        die(&format!("{path} reports ABI version {version}, want 1"));
    }

    unsafe {
        Abi {
            queue_create: std::mem::transmute(symbol("vsq_queue_create")),
            queue_destroy: std::mem::transmute(symbol("vsq_queue_destroy")),
            producer_create: std::mem::transmute(symbol("vsq_producer_create")),
            producer_destroy: std::mem::transmute(symbol("vsq_producer_destroy")),
            consumer_create: std::mem::transmute(symbol("vsq_consumer_create")),
            consumer_destroy: std::mem::transmute(symbol("vsq_consumer_destroy")),
            enqueue: std::mem::transmute(symbol("vsq_try_enqueue")),
            dequeue: std::mem::transmute(symbol("vsq_try_dequeue")),
        }
    }
}

fn die(message: &str) -> ! {
    eprintln!("FAIL - {message}");
    process::exit(1);
}

fn open_queue(abi: &Abi, capacity: u64, value_size: u64) -> (Handle, Handle, Handle) {
    let mut queue: *mut c_void = ptr::null_mut();
    let status = unsafe { (abi.queue_create)(capacity, value_size, 1, 1, &mut queue) };
    if status != STATUS_OK {
        die(&format!("vsq_queue_create returned {status}"));
    }
    let mut producer: *mut c_void = ptr::null_mut();
    let status = unsafe { (abi.producer_create)(queue, 0, &mut producer) };
    if status != STATUS_OK {
        die(&format!("vsq_producer_create returned {status}"));
    }
    let mut consumer: *mut c_void = ptr::null_mut();
    let status = unsafe { (abi.consumer_create)(queue, 0, &mut consumer) };
    if status != STATUS_OK {
        die(&format!("vsq_consumer_create returned {status}"));
    }
    (Handle(queue), Handle(producer), Handle(consumer))
}

fn close_queue(abi: &Abi, queue: Handle, producer: Handle, consumer: Handle) {
    unsafe {
        (abi.producer_destroy)(producer.0);
        (abi.consumer_destroy)(consumer.0);
        (abi.queue_destroy)(queue.0);
    }
}

// The trusted runner's payload shape and per-success consumer work, copied so
// the local producer/consumer cost balance matches the measured one.

fn prepare_payload(payload: &mut [u8], value: u64) {
    payload[..8].copy_from_slice(&value.to_le_bytes());
    let lane = (value >> 56) as u8;
    for (index, byte) in payload[8..].iter_mut().enumerate() {
        *byte = lane
            .wrapping_mul(31)
            .wrapping_add((index as u8).wrapping_mul(17))
            .wrapping_add(0x5d);
    }
}

fn validate_payload(payload: &[u8]) -> u64 {
    let value = u64::from_le_bytes(payload[..8].try_into().expect("eight-byte prefix"));
    let lane = (value >> 56) as u8;
    for (index, byte) in payload[8..].iter().enumerate() {
        let expected = lane
            .wrapping_mul(31)
            .wrapping_add((index as u8).wrapping_mul(17))
            .wrapping_add(0x5d);
        if *byte != expected {
            die(&format!("payload byte {} is {byte}, want {expected}", index + 8));
        }
    }
    value
}

fn mix_fingerprint(mut value: u64, key: u64) -> u64 {
    value = value.wrapping_add(key).wrapping_add(0x9e37_79b9_7f4a_7c15);
    value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^ (value >> 31)
}

fn add_fingerprint(target: &mut [u64; 2], keys: [u64; 2], value: u64) {
    for index in 0..2 {
        target[index] = target[index].wrapping_add(mix_fingerprint(value, keys[index]));
    }
}

struct Counts {
    enqueued: u64,
    full: u64,
    dequeued: u64,
    empty: u64,
    elapsed: f64,
}

fn measure_phase(abi: &Abi, capacity: u64, value_size: usize, duration: Duration) -> Counts {
    let (queue, producer, consumer) = open_queue(abi, capacity, value_size as u64);
    let keys = [0x51ed_2701_9f34_ab77_u64, 0xc2b2_ae3d_27d4_eb4f];
    let barrier = Arc::new(Barrier::new(3));
    let stop = Arc::new(AtomicBool::new(false));

    let (counts, elapsed) = thread::scope(|scope| {
        let producer_barrier = Arc::clone(&barrier);
        let producer_stop = Arc::clone(&stop);
        let producer_worker = scope.spawn(move || {
            let mut payload = vec![0_u8; value_size];
            let mut sequence = 0_u64;
            let mut enqueued = 0_u64;
            let mut full = 0_u64;
            let mut fingerprint = [0_u64; 2];
            prepare_payload(&mut payload, 0);
            unsafe { pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0) };
            producer_barrier.wait();
            let deadline = Instant::now() + duration;
            let mut attempts = 0_u64;
            while !producer_stop.load(Ordering::Relaxed) {
                if attempts % CLOCK_CHECK_INTERVAL == 0 && Instant::now() >= deadline {
                    break;
                }
                sequence = sequence.wrapping_add(1);
                let value = sequence & 0x00ff_ffff_ffff_ffff;
                payload[..8].copy_from_slice(&value.to_le_bytes());
                match unsafe { (abi.enqueue)(producer.0, payload.as_ptr(), value_size as u64) } {
                    STATUS_OK => {
                        enqueued += 1;
                        add_fingerprint(&mut fingerprint, keys, value);
                    }
                    STATUS_FULL => full += 1,
                    status => die(&format!("enqueue returned ABI status {status}")),
                }
                attempts = attempts.wrapping_add(1);
            }
            producer_stop.store(true, Ordering::Relaxed);
            (enqueued, full, fingerprint)
        });

        let consumer_barrier = Arc::clone(&barrier);
        let consumer_stop = Arc::clone(&stop);
        let consumer_worker = scope.spawn(move || {
            let mut output = vec![0_u8; value_size];
            let mut dequeued = 0_u64;
            let mut empty = 0_u64;
            let mut fingerprint = [0_u64; 2];
            unsafe { pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0) };
            consumer_barrier.wait();
            let deadline = Instant::now() + duration;
            let mut attempts = 0_u64;
            while !consumer_stop.load(Ordering::Relaxed) {
                if attempts % CLOCK_CHECK_INTERVAL == 0 && Instant::now() >= deadline {
                    break;
                }
                let mut length = 0_u64;
                let status = unsafe {
                    (abi.dequeue)(
                        consumer.0,
                        output.as_mut_ptr(),
                        value_size as u64,
                        &mut length,
                    )
                };
                match status {
                    STATUS_OK => {
                        if length as usize != value_size {
                            die(&format!("dequeue returned {length} bytes"));
                        }
                        let value = validate_payload(&output[..length as usize]);
                        dequeued += 1;
                        add_fingerprint(&mut fingerprint, keys, value);
                    }
                    STATUS_EMPTY => empty += 1,
                    status => die(&format!("dequeue returned ABI status {status}")),
                }
                attempts = attempts.wrapping_add(1);
            }
            consumer_stop.store(true, Ordering::Relaxed);
            (dequeued, empty, fingerprint)
        });

        barrier.wait();
        let start = Instant::now();
        let (enqueued, full, enqueued_fingerprint) =
            producer_worker.join().expect("producer thread");
        let (dequeued, empty, mut dequeued_fingerprint) =
            consumer_worker.join().expect("consumer thread");
        let elapsed = start.elapsed();

        // Final drain, exactly as the trusted runner does, so a candidate that
        // loses or fabricates items cannot post a rate here either.
        let mut output = vec![0_u8; value_size];
        let mut drained = 0_u64;
        loop {
            let mut length = 0_u64;
            let status = unsafe {
                (abi.dequeue)(
                    consumer.0,
                    output.as_mut_ptr(),
                    value_size as u64,
                    &mut length,
                )
            };
            match status {
                STATUS_OK => {
                    let value = validate_payload(&output[..length as usize]);
                    drained += 1;
                    if drained > capacity {
                        die("drained more than queue capacity");
                    }
                    add_fingerprint(&mut dequeued_fingerprint, keys, value);
                }
                STATUS_EMPTY => break,
                status => die(&format!("drain returned ABI status {status}")),
            }
        }
        if dequeued + drained != enqueued {
            die(&format!(
                "conservation failed: {enqueued} enqueued, {} returned",
                dequeued + drained
            ));
        }
        if dequeued_fingerprint != enqueued_fingerprint {
            die("dequeued values do not match the enqueued multiset");
        }

        (
            Counts {
                enqueued,
                full,
                dequeued,
                empty,
                elapsed: 0.0,
            },
            elapsed,
        )
    });

    close_queue(abi, queue, producer, consumer);
    Counts {
        elapsed: elapsed.as_secs_f64(),
        ..counts
    }
}

fn verify(abi: &Abi, capacity: u64, value_size: usize, items: u64) {
    let (queue, producer, consumer) = open_queue(abi, capacity, value_size as u64);

    thread::scope(|scope| {
        let producer_worker = scope.spawn(move || {
            let mut payload = vec![0_u8; value_size];
            let mut enqueued = 0_u64;
            while enqueued < items {
                payload[..8].copy_from_slice(&enqueued.to_le_bytes());
                match unsafe { (abi.enqueue)(producer.0, payload.as_ptr(), value_size as u64) } {
                    STATUS_OK => enqueued += 1,
                    STATUS_FULL => {}
                    status => die(&format!("enqueue returned ABI status {status}")),
                }
            }
            enqueued
        });
        let consumer_worker = scope.spawn(move || {
            let mut output = vec![0_u8; value_size];
            let mut dequeued = 0_u64;
            while dequeued < items {
                let mut length = 0_u64;
                let status = unsafe {
                    (abi.dequeue)(
                        consumer.0,
                        output.as_mut_ptr(),
                        value_size as u64,
                        &mut length,
                    )
                };
                match status {
                    STATUS_OK => {
                        if length as usize != value_size {
                            die(&format!("dequeue returned {length} bytes"));
                        }
                        let value = u64::from_le_bytes(output[..8].try_into().expect("prefix"));
                        if value != dequeued {
                            die(&format!("expected sequence {dequeued}, saw {value}"));
                        }
                        dequeued += 1;
                    }
                    STATUS_EMPTY => {}
                    status => die(&format!("dequeue returned ABI status {status}")),
                }
            }
            dequeued
        });
        let enqueued = producer_worker.join().expect("producer thread");
        let dequeued = consumer_worker.join().expect("consumer thread");
        if enqueued != items || dequeued != items {
            die(&format!("expected {items} items, saw {enqueued}/{dequeued}"));
        }
    });

    let mut output = vec![0_u8; value_size];
    let mut length = 0_u64;
    let status = unsafe {
        (abi.dequeue)(
            consumer.0,
            output.as_mut_ptr(),
            value_size as u64,
            &mut length,
        )
    };
    if status != STATUS_EMPTY {
        die(&format!("queue was not empty after the drain: status {status}"));
    }
    close_queue(abi, queue, producer, consumer);
    println!("PASS - {items} items in order at capacity {capacity}, value size {value_size}");
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!(
            "usage:\n  {0} measure <library> [capacity] [value_size] [warmup_s] [duration_s]\n  \
             {0} verify <library> [capacity] [value_size] [items]",
            args[0]
        );
        process::exit(2);
    }
    let mode = args[1].as_str();
    let library = args[2].as_str();
    let abi = load(library);
    let capacity: u64 = args.get(3).map_or(1024, |value| value.parse().expect("capacity"));
    let value_size: usize = args
        .get(4)
        .map_or(8, |value| value.parse().expect("value size"));

    match mode {
        "measure" => {
            let warmup: f64 = args.get(5).map_or(1.0, |v| v.parse().expect("warmup"));
            let duration: f64 = args.get(6).map_or(3.0, |v| v.parse().expect("duration"));
            if warmup > 0.0 {
                measure_phase(&abi, capacity, value_size, Duration::from_secs_f64(warmup));
            }
            let counts = measure_phase(
                &abi,
                capacity,
                value_size,
                Duration::from_secs_f64(duration),
            );
            let successful = counts.enqueued + counts.dequeued;
            println!(
                "library={library} capacity={capacity} value_size={value_size} \
                 enqueued={} full={} dequeued={} empty={} elapsed={:.6} total_ops_per_sec={:.1}",
                counts.enqueued,
                counts.full,
                counts.dequeued,
                counts.empty,
                counts.elapsed,
                successful as f64 / counts.elapsed,
            );
        }
        "verify" => {
            let items: u64 = args.get(5).map_or(2_000_000, |v| v.parse().expect("items"));
            verify(&abi, capacity, value_size, items);
        }
        other => die(&format!("unknown mode {other:?}")),
    }
}

args.command:
python3 - <<'PY'
p='bench/spsc_harness.rs'
s=open(p).read()
s=s.replace("""#[derive(Clone, Copy)]
struct Handle(*mut c_void);
unsafe impl Send for Handle {}
""","""#[derive(Clone, Copy)]
struct Handle(*mut c_void);
unsafe impl Send for Handle {}

impl Handle {
    /// Taking `self` by value keeps closure capture at whole-`Handle`
    /// granularity, which is what makes the handle `Send` into a worker.
    fn ptr(self) -> *mut c_void {
        self.0
    }
}
""",1)
s=s.replace("producer.0","producer.ptr()").replace("consumer.0","consumer.ptr()").replace("queue.0","queue.ptr()")
open(p,'w').write(s)
PY
export TMPDIR=/tmp
rustc -O --edition 2021 bench/spsc_harness.rs -o /tmp/spsc_harness 2>&1 | head -30; ls -la /tmp/spsc_harness 2>&1
